 $out=['provider_active'=>cyberdat_research_active(),'provider_store'=>!empty($d['fallback'])?'last_verified_file_cache':'research_database_projection','snapshot_selected'=>$v['cache']['snapshot']??null,'sql_items'=>$s->prefix.'items','sql_projection'=>$s->prefix.'state.dashboard','database_kev_active'=>(int)$s->db->get_var("SELECT COUNT(*) FROM {$s->prefix}items WHERE source='kev' AND active=1"),'database_nvd'=>$s->count('nvd'),'catalog_kev'=>$v['cache']['catalog']['count']??0,'catalog_version'=>$v['cache']['catalog']['catalogVersion']??null,'catalog_released'=>$v['cache']['catalog']['dateReleased']??null,'projection_generated'=>$d['generated_at']??0,'projection_indexed'=>$d['indexed_cves']??0,'kev_matched_nvd'=>$c['loaded'],'matched_projection_limit'=>2000,'nvd_window'=>$d['nvd_window']??null,'nvd_checkpoint'=>$d['nvd_checkpoint']??null,'health'=>$health,'samples'=>$samples,'legacy_snapshot_present'=>(bool)($legacy['snapshot']??false),'legacy_catalog_version'=>$legacy['catalog']['catalogVersion']??null,'legacy_fetched_at'=>$legacy['fetched_at']??null];
